CREATE OR REPLACE FUNCTION public.account_erasure_attachment_classify(p_profile_id uuid, p_paths text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
